		default:
			log.Printf("WARN [config] cannot read %s to look for the price example, saving without it: %v", configPath, readErr)
		}
	}

	// Marshal to YAML
	data, err := marshalContext(cfg, withExample)
	if err != nil {
		return err
	}

	// Write the file
	return os.WriteFile(configPath, data, 0600)'''
